<script setup lang="ts">
import { useVueFlow } from '@vue-flow/core'
import { Trash2, Palette } from 'lucide-vue-next'
import type { StickyAnnotation } from '~/composables/useCanvasAnnotations'
import { STICKY_COLORS, isDarkPaper } from '~/composables/useCanvasAnnotations'

const props = defineProps<{
  annotation: StickyAnnotation
  /** Selected state — owned by the canvas (one sticky at a time, like arrows). */
  selected?: boolean
}>()

const emit = defineEmits<{
  'drag': [id: string, dx: number, dy: number]
  'resize': [id: string, w: number, h: number]
  'update': [id: string, patch: Partial<StickyAnnotation>]
  'remove': [id: string]
  'select': [id: string]
}>()

const { viewport } = useVueFlow()

const isEditing = ref(false)
const textareaRef = ref<HTMLTextAreaElement | null>(null)

// Drag from anywhere on the sticky — including the (readonly) textarea, since
// that occupies most of the body and excluding it would leave a tiny strip
// around the edge as the only drag handle. When editing, drag is suppressed
// so click-to-position-cursor and text selection work normally.
let dragLast: { x: number; y: number } | null = null
function onPointerDown(e: PointerEvent) {
  if (isEditing.value) return
  if (e.button !== 0) return
  // Bail only for actual interactive controls — buttons (toolbar / color
  // picker). The textarea is fine to initiate drag from when readonly.
  const target = e.target as HTMLElement
  if (target.closest('button')) return
  e.stopPropagation()
  // Any press selects — a plain click and the start of a drag both count.
  emit('select', props.annotation.id)
  ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)
  dragLast = { x: e.clientX, y: e.clientY }
}
function onPointerMove(e: PointerEvent) {
  if (!dragLast) return
  const zoom = viewport.value.zoom || 1
  const dx = (e.clientX - dragLast.x) / zoom
  const dy = (e.clientY - dragLast.y) / zoom
  dragLast = { x: e.clientX, y: e.clientY }
  emit('drag', props.annotation.id, dx, dy)
}
function onPointerUp(e: PointerEvent) {
  if (!dragLast) return
  ;(e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId)
  dragLast = null
}

// Resize from bottom-right.
let resizeLast: { x: number; y: number; w: number; h: number } | null = null
function onResizeDown(e: PointerEvent) {
  if (e.button !== 0) return
  e.stopPropagation()
  emit('select', props.annotation.id)
  ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)
  resizeLast = { x: e.clientX, y: e.clientY, w: props.annotation.width, h: props.annotation.height }
}
function onResizeMove(e: PointerEvent) {
  if (!resizeLast) return
  const zoom = viewport.value.zoom || 1
  const dx = (e.clientX - resizeLast.x) / zoom
  const dy = (e.clientY - resizeLast.y) / zoom
  emit('resize', props.annotation.id, resizeLast.w + dx, resizeLast.h + dy)
}
function onResizeUp(e: PointerEvent) {
  ;(e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId)
  resizeLast = null
}

function startEdit() {
  isEditing.value = true
  nextTick(() => {
    textareaRef.value?.focus()
    textareaRef.value?.select()
  })
}

// Conditional pointerdown on the textarea: only swallow the event while
// editing so the parent drag handler picks it up otherwise.
function onTextareaPointerDown(e: PointerEvent) {
  if (isEditing.value) e.stopPropagation()
}
function commitEdit() {
  isEditing.value = false
  // text is already bound via v-model below; nothing else to do.
}

// Local model for the textarea so we can debounce-emit changes via blur.
const textDraft = ref(props.annotation.text)
watch(() => props.annotation.text, (v) => { textDraft.value = v })
function onTextInput() {
  emit('update', props.annotation.id, { text: textDraft.value })
}

const showColorBar = ref(false)
function pickColor(c: string) {
  emit('update', props.annotation.id, { color: c })
  showColorBar.value = false
}

// Sticky-paper feel: subtle paper-grain via a layered gradient. The rotation
// is per-instance random (set at create time) — small, just enough to feel
// hand-placed rather than software-stamped.
const rotation = computed(() => props.annotation.rotation ?? 0)
// Dark papers flip the text and chrome to light (see --dark rules).
const isDark = computed(() => isDarkPaper(props.annotation.color))

// Foil glitter (Pokémon-card style, à la simeydotme): a static field of
// small silvery dots. At rest they're barely there; a wide light band sweeps
// across and the dots UNDER it appear, with one narrow rainbow ray inside
// the band — the shimmer lives on the dots, never as a wash over the paper. Nothing animates on its own:
// the band and the hue cycle are driven by the CANVAS PAN, so the foil only
// glints while the user moves the canvas, like light raking over a card.
// Each sticky adds its own canvas position into the phase so neighbours
// glint at different moments instead of in lockstep.
const shimmerPhase = computed(() => {
  const vp = viewport.value
  return (vp.x + vp.y) * 0.7
    + (props.annotation.x + props.annotation.y) * (vp.zoom || 1) * 0.35
})
// The band mask (and the rainbow ray riding inside it) slide with the pan
// at 1.6× so the light rakes across the paper.
const bandPosition = computed(() => `${(shimmerPhase.value * 1.6).toFixed(1)}px 0px`)
const glitterStyle = computed(() => ({}))
const glintStyle = computed(() => ({
  maskPosition: bandPosition.value,
  WebkitMaskPosition: bandPosition.value,
}))
const rayStyle = computed(() => ({
  backgroundPosition: bandPosition.value,
}))
</script>

<template>
  <div
    class="sticky-annotation absolute pointer-events-auto"
    :class="{ 'sticky-annotation--dark': isDark, 'sticky-annotation--selected': selected }"
    :style="{
      left: `${annotation.x}px`,
      top: `${annotation.y}px`,
      width: `${annotation.width}px`,
      height: `${annotation.height}px`,
      transform: `rotate(${rotation}deg)`,
      backgroundColor: annotation.color, // -color, not the shorthand: keep the class's paper gradient
    }"
    @pointerdown="onPointerDown"
    @pointermove="onPointerMove"
    @pointerup="onPointerUp"
    @pointercancel="onPointerUp"
    @dblclick.stop="startEdit"
  >
    <!-- Foil shimmer: glitter specks + sheen band, both positioned by the
         canvas pan (see shimmerPhase). Purely decorative — sits under the
         text, ignores the pointer. -->
    <div class="sticky-annotation__shimmer" aria-hidden="true">
      <div class="sticky-annotation__glitter" :style="glitterStyle" />
      <div class="sticky-annotation__glint" :style="glintStyle" />
      <div v-for="i in 4" :key="i" :class="`sticky-annotation__ray sticky-annotation__ray--${i - 1}`" :style="rayStyle" />
    </div>

    <!-- Body: textarea always present; just toggles between read-only and editable.
         pointerdown is conditionally stopped: while editing, we stop it so
         the parent's drag handler doesn't hijack click-to-position-cursor;
         while readonly, we let it bubble so the user can drag from the body. -->
    <!-- Escape leaves text editing but keeps the note selected (the canvas
         handles the second Escape / Delete once nothing is being typed). -->
    <textarea
      @keydown.esc.stop="(e) => (e.target as HTMLTextAreaElement).blur()"
      ref="textareaRef"
      v-model="textDraft"
      class="sticky-annotation__text"
      :readonly="!isEditing"
      placeholder="Type a note…"
      @blur="commitEdit"
      @input="onTextInput"
      @pointerdown="onTextareaPointerDown"
      @keydown.escape.prevent="commitEdit"
    />

    <!-- Toolbar: appears on hover via CSS. Color picker + delete. -->
    <div class="sticky-annotation__toolbar" @pointerdown.stop>
      <button
        v-if="STICKY_COLORS.length > 1"
        type="button"
        class="sticky-annotation__btn"
        title="Color"
        @click.stop="showColorBar = !showColorBar"
      >
        <Palette class="w-3 h-3" />
      </button>
      <button
        type="button"
        class="sticky-annotation__btn sticky-annotation__btn--danger"
        title="Delete"
        @click.stop="emit('remove', annotation.id)"
      >
        <Trash2 class="w-3 h-3" />
      </button>
    </div>

    <!-- Color picker strip. Lives inside the sticky so it inherits the rotation. -->
    <div
      v-if="showColorBar"
      class="sticky-annotation__colors"
      @pointerdown.stop
    >
      <button
        v-for="c in STICKY_COLORS"
        :key="c"
        type="button"
        class="sticky-annotation__swatch"
        :style="{ background: c }"
        :aria-label="`Set color ${c}`"
        @click.stop="pickColor(c)"
      />
    </div>

    <!-- Resize handle. -->
    <div
      class="sticky-annotation__resize"
      @pointerdown="onResizeDown"
      @pointermove="onResizeMove"
      @pointerup="onResizeUp"
      @pointercancel="onResizeUp"
    />
  </div>
</template>

<style scoped>
.sticky-annotation {
  border-radius: 2px;
  /* Layered shadow: a tight contact shadow + a soft cast shadow. Reads as
     physical paper without being heavy on dark backgrounds. */
  box-shadow:
    0 1px 1px rgba(0, 0, 0, 0.18),
    0 6px 14px rgba(0, 0, 0, 0.28);
  /* Light-grey diagonal gradient over the paper colour — gives the screen-
     blended shimmer something to glow against (flat white has no headroom). */
  background-image: linear-gradient(135deg,
    rgba(255, 255, 255, 0.70) 0%, rgba(255, 255, 255, 0) 35%,
    rgba(0, 0, 0, 0.10) 65%, rgba(0, 0, 0, 0.22) 100%);
  display: flex;
  flex-direction: column;
}

/* ── Dark paper ────────────────────────────────────────────────────────────
   Graphite / ink stickies: light text and chrome, a much softer paper
   gradient (the white sheen that lifts white paper would turn a black note
   grey), and the screened glitter reads brighter by nature. */
.sticky-annotation--dark {
  background-image: linear-gradient(135deg,
    rgba(255, 255, 255, 0.10) 0%, rgba(255, 255, 255, 0) 40%,
    rgba(0, 0, 0, 0.18) 70%, rgba(0, 0, 0, 0.35) 100%);
}
.sticky-annotation--dark .sticky-annotation__text {
  color: rgba(245, 245, 243, 0.92);
}
.sticky-annotation--dark .sticky-annotation__text::placeholder {
  color: rgba(245, 245, 243, 0.42);
}
.sticky-annotation--dark .sticky-annotation__btn {
  background: rgba(255, 255, 255, 0.12);
  color: rgba(245, 245, 243, 0.75);
}
.sticky-annotation--dark .sticky-annotation__btn:hover {
  background: rgba(255, 255, 255, 0.22);
  color: rgba(245, 245, 243, 0.98);
}
.sticky-annotation--dark .sticky-annotation__resize {
  background: linear-gradient(135deg, transparent 50%, rgba(255, 255, 255, 0.35) 50%);
}
.sticky-annotation--dark .sticky-annotation__glitter {
  opacity: 0;
}
.sticky-annotation--dark .sticky-annotation__glint {
  opacity: 0.035; /* screen has huge headroom on black — owner wants it hardly visible */
}
.sticky-annotation--dark .sticky-annotation__ray {
  opacity: 0.05;
}
/* Dark papers get a dark-grey→black hairline instead of white→black. */
.sticky-annotation.sticky-annotation--dark::after { /* out-specifies the base ::after below */
  background: linear-gradient(180deg, #4a4a4e 0%, #000000 100%);
}

/* Selected: an action-blue ring just outside the hairline, plus the paper's
   own shadows. Same on light and dark papers — blue is Sailor's one accent. */
.sticky-annotation--selected {
  box-shadow:
    0 0 0 1.5px #4f8cff,
    0 0 0 4px rgba(79, 140, 255, 0.28),
    0 1px 1px rgba(0, 0, 0, 0.18),
    0 6px 14px rgba(0, 0, 0, 0.28);
}

/* Hairline stroke: a 1px ring carrying a vertical white→black gradient
   (borders can't take gradients, so it's a padded pseudo-element masked to
   its own border ring). Sits above the text layer but only ever covers the
   outermost pixel, well outside the textarea's padding. */
.sticky-annotation::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(180deg, #ffffff 0%, #000000 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  z-index: 3;
}

/* ── Foil glitter ─────────────────────────────────────────────────────────
   Modelled on the reference card: a dense, even scatter of small SILVERY
   dots (procedural SVG tile — jittered square lattice, bounded jitter so no
   two dots touch, r≈0.55–1px) that is invisible until a wide soft light
   band passes over it, plus ONE narrow rainbow ray riding inside that band
   (the rest of the shimmer stays white/grey). Nothing self-animates: band
   and ray positions are driven by the canvas pan (see shimmerPhase).
   - glitter: the resting dots at near-zero opacity.
   - glint: the same dots at full strength, masked by the moving band.
   - ray ×4: the spectrum streak, cut through four random subsets of the
     dots with per-layer hue offsets (trend + per-dot scatter), moving with
     the band. Its gradient tile is transparent at both edges, so the tile
     seam is never visible. blur(0.2px) on every layer. */
.sticky-annotation__shimmer {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  pointer-events: none;
}
.sticky-annotation__glitter,
.sticky-annotation__glint,
.sticky-annotation__ray {
  position: absolute;
  inset: 0;
  -webkit-mask-repeat: repeat;
  mask-repeat: repeat;
}
.sticky-annotation__glitter,
.sticky-annotation__glint {
